#!/usr/bin/env bash
# step78 — WhatsApp module Phase 2b: Verify-with-WhatsApp UX + status polling +
# inbound bot webhook. Adds routes/whatsapp.js and views/account/whatsapp.ejs,
# refreshes the dashboard, mounts the router, and shows a WhatsApp card.
# Graceful before the bot exists. Idempotent; rolls back the 3 touched files.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step78-$TS
mkdir -p "$BAK/routes" "$BAK/views/account"
cp "$APP/server.js" "$BAK/server.js"
cp "$APP/routes/account.js" "$BAK/routes/account.js"
cp "$APP/views/account/dashboard.ejs" "$BAK/views/account/dashboard.ejs"
restore(){ echo "!! rollback"; cp "$BAK/server.js" "$APP/server.js"; cp "$BAK/routes/account.js" "$APP/routes/account.js"; cp "$BAK/views/account/dashboard.ejs" "$APP/views/account/dashboard.ejs"; rm -f "$APP/routes/whatsapp.js" "$APP/views/account/whatsapp.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> write new files"
w(){ mkdir -p "$(dirname "$APP/$1")"; base64 -d > "$APP/$1"; }
w routes/whatsapp.js <<'B64'

B64
w views/account/whatsapp.ejs <<'B64'

B64
w views/account/dashboard.ejs <<'B64'

B64

echo "==> patch routes/account.js (dashboard WhatsApp status)"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/routes/account.js'; let s=fs.readFileSync(f,'utf8');
const anc="    res.render('account/dashboard', Object.assign(await shell(), { title: 'My account', c, ok: req.query.ok || null }));";
if(s.indexOf('waStatusLink')>=0){ console.log('   account.js already patched'); }
else {
  if(s.indexOf(anc)<0){ console.error('!! account render anchor not found'); process.exit(2); }
  const repl="    let wa={verified:false,phone:''}; /*waStatusLink*/\n    try{ const L=(await pool.query(\"SELECT i.current_phone_e164 FROM customer_whatsapp_links l JOIN whatsapp_identities i ON i.id=l.whatsapp_identity_id WHERE l.customer_id=$1 AND l.status='ACTIVE' AND l.is_primary=true LIMIT 1\",[c.id])).rows[0]; if(L){ wa.verified=true; wa.phone=L.current_phone_e164||''; } }catch(e){}\n    res.render('account/dashboard', Object.assign(await shell(), { title: 'My account', c, ok: req.query.ok || null, wa }));";
  s=s.replace(anc, repl); fs.writeFileSync(f,s); console.log('   account.js patched');
}
NODE

echo "==> patch server.js (mount whatsapp router)"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/server.js'; let s=fs.readFileSync(f,'utf8');
if(s.indexOf('routes/whatsapp')>=0){ console.log('   server.js already patched'); }
else {
  const anc="const accountRouter = require('./routes/account')(pool);\napp.use('/', accountRouter);";
  if(s.indexOf(anc)<0){ console.error('!! account mount anchor not found'); process.exit(3); }
  s=s.replace(anc, anc+"\nconst whatsappRouter = require('./routes/whatsapp')(pool);\napp.use('/', whatsappRouter);");
  fs.writeFileSync(f,s); console.log('   server.js patched');
}
NODE

echo "==> node --check"; node --check "$APP/routes/whatsapp.js"; node --check "$APP/routes/account.js"; node --check "$APP/server.js"
echo "==> ejs compile"
node <<'NODE'
const ejs=require('ejs'),fs=require('fs');
['views/account/whatsapp.ejs','views/account/dashboard.ejs'].forEach(v=>{ ejs.compile(fs.readFileSync('/opt/gsz/'+v,'utf8'),{filename:'/opt/gsz/'+v}); console.log('   compiled '+v); });
NODE

echo "==> pm2 restart"; pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
C1=$(curl -s -o /dev/null -w '%{http_code}' -m 10 http://127.0.0.1:3900/account/whatsapp || true)
echo "   /account/whatsapp (no session) -> HTTP $C1"; [ "$C1" = "302" ] || { echo "!! should redirect to login"; false; }

echo "==> webhook self-test (simulates the bot)"
SECRET=$(node -e "require('dotenv').config();const {Pool}=require('pg');const p=new Pool({host:process.env.DB_HOST,port:process.env.DB_PORT,database:process.env.DB_NAME,user:process.env.DB_USER,password:process.env.DB_PASS});p.query(\"SELECT value FROM wa_settings WHERE key='wa_bot_webhook_secret'\").then(r=>{process.stdout.write(r.rows[0]?r.rows[0].value:'');return p.end();}).catch(()=>p.end());")
WU=$(curl -s -o /dev/null -w '%{http_code}' -m 10 -X POST http://127.0.0.1:3900/internal/whatsapp/incoming -H 'Content-Type: application/json' -d '{"text":"hi"}' || true)
echo "   no-secret call -> HTTP $WU"; [ "$WU" = "401" ] || { echo "!! webhook must reject without secret"; false; }
WB=$(curl -s -m 10 -X POST http://127.0.0.1:3900/internal/whatsapp/incoming -H 'Content-Type: application/json' -H "X-WA-Secret: $SECRET" -d '{"from":"923001112222@s.whatsapp.net","text":"hello there"}' || true)
grep -q '"action":"REDIRECT"' <<<"$WB" || { echo "!! webhook redirect self-test failed: $WB"; false; }
echo "   junk message -> redirect reply OK"
# reset bot status (the self-test set a heartbeat; real bot isn't live yet)
node -e "require('dotenv').config();const {Pool}=require('pg');const p=new Pool({host:process.env.DB_HOST,port:process.env.DB_PORT,database:process.env.DB_NAME,user:process.env.DB_USER,password:process.env.DB_PASS});p.query(\"UPDATE wa_settings SET value='DISCONNECTED' WHERE key='wa_bot_status'\").then(()=>p.end()).catch(()=>p.end());" >/dev/null 2>&1 || true
trap - ERR
echo "==> step78 OK — Verify-with-WhatsApp flow live. Backup: $BAK"
echo "   Page: /account/whatsapp  |  Webhook: POST /internal/whatsapp/incoming (secret-gated)"
